// Every vessel the 2D anatomy draws, as a 3D course named by its hales-engine topology edge ID. The courses are the 2D figure's own (paths.copied.ts: its 64
// samples a vessel, meander included, generated by scripts/copy-b3-data.mjs), carried by the one linear map of frame2d.ts and given depth by the 2D figure's
// own tiers (frame2d.ts TIER_Z): nothing is placed by hand, warped or smoothed. A vessel's width is the 2D figure's (widthAt: vesselPx of its diameter, the
// liver's beds fixed, the arteries half, the cava three quarters, with the few named exceptions), in the same units, so it is the same width on the plate.
import { Vector3 } from 'three';
import { EDGES, JUNCTION_PIECES, PART_OF, PORTAL_TERRITORY, dMinOf } from '../../engine/hales/portal/topology.js';
import { ANAT_HIDDEN, BACK_EDGES, EDGE_PATH_2D, HIDDEN_EDGES, IVC_EDGES, NEEDS_C3 } from './paths.copied.ts';
import { FEEDERS_2D, STRANDS_2D, type Feeder2D } from './coil.copied.ts';
import { isCoiling } from './coil.ts';
import { type JoinEdge, type RunOn, findRunOns, smoothRunOns } from './joins.ts';
import { ORGAN_Z } from '../organs/z.ts';
import { ALONG_VEIN_IDS, LEAVE_VEIN_IDS, alongVein, leaveVein } from './starts.ts';
import { LIVER_BRANCHES, LIVER_BRANCH_HOSTS, SPLIT_AT, trimHost } from './liver-branches.ts';
import { CAUDATE_VEIN_ID, caudateVeinSet } from './caudate-veins.ts';
import { withStartInOrgan } from './starts.ts';
import type { Vec3 } from '../anatomy/vessels.ts';
import { TIER_Z, type Tier, UNITS_PER_SCENE, len3, x3, y3 } from '../frame2d.ts';

export interface Flare { add: number; wall: number; span: number }
export type NetTone = 'portal' | 'sys' | 'artery';
export type { Tier };
export interface NetVessel {
  /** hales-engine topology edge ID (a piece's own ID when the engine cuts the vein where a shunt or collateral joins it) */
  id: string;
  /** the whole vein this piece belongs to (its own ID when not cut) */
  host: string;
  from: string; to: string;
  tone: NetTone;
  /** scene radius at the diameter the course was built at (`baseD`) */
  radius: number;
  label: string;
  /** centreline in flow order */
  pts: Vec3[];
  kind: string;
  /** the Circuit's finer artery (2D AP_FINE): 0.6 on an arterioportal shunt, else 1 */
  circFine?: number;
  tier: Tier;
  /** the diameter (mm) `radius` belongs to; the width then follows the engine's diameter by the 2D rule (`widthKind`) */
  baseD: number;
  /** 0: vesselPx of the diameter; 1: an artery (half of it, at least 1.8); 2: fixed (the liver's beds) */
  widthKind: 0 | 1 | 2;
  /** the edge whose data texel (pressure, flow, diameter) this vessel wears: its own, or its host's for a feeder */
  lensId: string;
  /** a branch of a vessel (liver-branches.ts): the stretch of its host's lens ramp it wears, 0 to 1 */
  lensSpan?: readonly [number, number];
  /** how its shape is made: a vessel's own course, coiled and with strands (a collateral or a liver bed), or a fan of tributaries on a host */
  plan?: { kind: 'coil'; base: readonly (readonly [number, number])[]; coils: boolean; strands: boolean } | { kind: 'feeder'; list: readonly (Feeder2D & { dz?: readonly number[]; taper?: readonly [number, number]; taperSpan?: readonly [number, number]; join?: 0 | 1; atEnd?: true })[]; cfgK: number; hostW: number; when: string | null };
  /** the radius at each end as a share of `radius`, where this vessel runs on into exactly one other (no branch): both ease to their mean, so no step shows at the join */
  taper?: readonly [number, number];
  /** where this vessel ends on a trunk without running on into it (a branch of a fork): a collar that blooms where the branch meets the host's wall, the 2D figure's fillet (the smooth union of the
   *  two tubes, blend k of fork-joins / vein-joins kOf): `add` more radius at the wall, `wall` the distance from the end to the host's wall, `span` the length the collar takes to melt into the tube */
  flare?: readonly [Flare | null, Flare | null];
  /** the ends that run on into another vessel (a node of exactly two, or the pair the 2D rule picks at a fork), their tubes meeting end to end: no round cap there (a cap is a ball of ink and, in the veil, a second layer where the two tubes overlap) */
  joined?: readonly [boolean, boolean];
  /** a tributary group: drawn only while its rule holds (`when`: null always; 'caput' with the paraumbilical collateral; 'caudate' with the caudate vein's rise) */
  feeder?: { host: string; when: string | null };
}

interface Edge { id: string; from: string; to: string; kind: string; d?: number; dMax?: number; share?: number; label?: string; zone?: string; shunt?: string; spontaneous?: boolean }
const edges = EDGES as Edge[];
const edgeById = new Map(edges.map((e) => [e.id, e]));
const portal = PORTAL_TERRITORY as Set<string>;

// ---- widths: stage-tubes.js widthAt (anatomy, t = 0), in the figure's own units ----
const CALIBER = 1.3;
/** stage.js vesselPx: a vein's width in the figure's units from its diameter in mm. */
export const vesselPx = (dmm: number): number => CALIBER * Math.max(2.6, 2.0 * Math.pow(Math.max(0.1, dmm), 0.72));
const AP_FINE = 0.6;
export const isArteryEdge = (e: Edge): boolean => e.kind === 'artery' || e.kind === 'arteriole' || (e.kind === 'shunt' && e.shunt === 'ap');
const IVC_ONE_D = () => edgeById.get('IVC_IS')!.d!;

/** The figure's width of edge `e` at diameter `dmm`, before the per-vessel exceptions. */
export function widthPx(e: Edge, dmm: number): number {
  if (e.kind === 'liver') return e.zone === 'sin' || e.zone === 'inter' || e.zone === 'post' ? 3.6 : 5.2;
  if (isArteryEdge(e)) return Math.max(1.8, vesselPx(dmm) * 0.5 * (e.shunt === 'ap' ? AP_FINE : 1));
  // (a vein the engine cuts in pieces where a shunt or a collateral joins it is ONE vein: every exception is keyed by the whole vein's id, not the piece's, or its pieces are drawn at different calibres and the vein steps
  //  where they meet: the superior cava's upper piece was 1.39 times as wide as its lower one, 2D's own step (stage-tubes.js keys the 0.72 by the piece), which the smooth joins could only soften into a bulge. Mohammad, 20 Nov: "smooth calibres across the entirety of the app")
  const whole = (PART_OF as Record<string, string | undefined>)[e.id] ?? e.id;
  let w = vesselPx(IVC_EDGES.has(e.id) ? IVC_ONE_D() : dmm) * (IVC_EDGES.has(e.id) || whole === 'SVC_RA' || whole === 'V_UP' ? 0.72 : 1);
  if (e.id === 'C8') w *= 0.6;
  if (e.id === 'C3') w *= 0.6;   // the paraumbilical vein is a branch of the left portal vein, not as wide as it: it leaves it as a filleted Y (the fork rule), not a blunt stack of equal tubes (Mohammad, 20 Nov)
  if (whole === 'LGV_CONF') w *= 0.85;
  return w;
}
/** The tube's smallest radius in the figure's units (stage-tubes.js tubeRadius: max(0.35, w / 2)). */
export const radiusOf = (wpx: number): number => len3(Math.max(0.35, wpx / 2));
const widthKindOf = (e: Edge): 0 | 1 | 2 => (e.kind === 'liver' ? 2 : isArteryEdge(e) ? 1 : 0);

// ---- tiers: stage.js (front / over lists, BACK_EDGES, arteries, collaterals) ----
const FRONT_IDS = new Set(['PV_TRUNK', 'PV_TRUNK_1', 'PVH_R', 'PVH_R_1', 'PVH_R_2', 'PVH_L', 'PVH_L_1', 'SMV_CONF', 'SV_CONF']);
const OVER_IDS = new Set(['TIPS', 'DIPS', 'C6', 'S_DSR', 'S_PC', 'C8', 'S_MC', 'REX']);
const hostOfPiece = new Map<string, string>();
for (const [host, pieces] of Object.entries(JUNCTION_PIECES as Record<string, string[]>)) for (const p of pieces) hostOfPiece.set(p, host);

/** The renal vein runs at the cava's depth, and the kidney is placed there too (Mohammad, 20 Nov: "the renal vein and the kidney should be at the same depth as the IVC"). Depth only:
 *  it is still drawn the way the 2D figure draws it (BACK_EDGES, in the scene, is what puts a vessel behind the organs). */
export const RENAL_VEIN_IDS: ReadonlySet<string> = new Set(['V_KID_L', 'V_KID_L_1', 'LRV_IVC']);
/** The hepatic veins lie on the cava's plane too: they join it level, with no depth to ease, so a tilted view shows no twist where they meet (Mohammad, 20 Nov). */
export const HEPATIC_VEIN_IDS: ReadonlySet<string> = new Set(['RHV_IVC', 'RHV_IVC_1', 'MHV_IVC', 'LHV_IVC']);
function tierOf(e: Edge): Tier {
  if (BACK_EDGES.has(e.id) || RENAL_VEIN_IDS.has(e.id)) return 'back';
  if (HEPATIC_VEIN_IDS.has(e.id)) return 'hv';   // (the cava's plane, 0.016 in front of it: the lumbar collaterals that cross them stay apart in depth)
  if (e.id === 'C3') return 'fwd';   // the paraumbilical vein rises forward over the portal trunk to the umbilicus
  if (isArteryEdge(e)) return 'art';
  if (OVER_IDS.has(e.id)) return 'over';
  if (e.kind === 'collateral') return 'mid';
  if (e.kind === 'vein' && portal.has(e.to) && portal.has(e.from || '') || FRONT_IDS.has(e.id)) return 'front';
  return 'net';
}
const toneOf = (e: Edge): NetTone => (isArteryEdge(e) ? 'artery' : portal.has(e.from) || portal.has(e.to) ? 'portal' : 'sys');

/** The 2D course of an edge carried into the scene: x and y by the linear map, z by its tier. */
export function courseOf(id: string): Vec3[] {
  const e = edgeById.get(id)!, z = TIER_Z[tierOf(e)];
  return pathOf(id).map(([x, y]): Vec3 => [x3(x), y3(y), z]);
}

/** The shunts a procedure makes (B5): drawn while the engine gives them a diameter (stage-frame.js edgeVisible: `D > 0`). */
export const SHUNT_IDS: ReadonlySet<string> = new Set(['TIPS', 'DIPS', 'S_PC', 'S_DSR', 'S_MC', 'REX']);
/** Their diameter when a procedure puts them in, mm: the width they are drawn at when the engine's live diameter is read against it. */
const SHUNT_BASE_D: Record<string, number> = { TIPS: 8, DIPS: 8 };

/** The edges the figure draws as vessels (kinds the engine models but the anatomy never draws are left out: the catheter wedge beds, the one-way
 *  diode, the gut-side arterioles; surgical shunts and the stents belong to the procedures (B5)). */
export function isDrawnEdge(e: Edge): boolean {
  if (HIDDEN_EDGES.has(e.id) || ANAT_HIDDEN.has(e.id) || e.id === 'CAUD') return false;   // (V_UP, the brachiocephalic veins, IS drawn: it is the superior cava's own run up out of the figure, fading to nothing as 2D's FADE_DOWN_Y says; leaving it out ended the cava in a blunt cap at the azygos and gave the Circuit no stretch above the azygos)
  if (e.kind === 'wedge' || e.kind === 'diode') return false;
  // (the arterioportal shunts are never drawn: Mohammad, 20 Nov, "remove the arterioportal fistulas completely no matter what"; the engine still has them, its numbers are unchanged)
  if (e.kind === 'shunt') return e.shunt !== 'ap' && SHUNT_IDS.has(e.id);
  return true;
}

/** Tributary fans that are not drawn: the caudate lobe's twigs hung in the middle of the liver joined to nothing (Mohammad, 20 Nov: "random veins in the middle of the liver not
 *  connected to anything, remove them"). The caudate's own drainage stays in its card (details: CAUD). */
const NOT_DRAWN_FEEDERS: ReadonlySet<string> = new Set(['CAUD', 'AZY_SVC']);   // (AZY_SVC: the azygos' tributary strand ran up the figure's right and arched over the SVC's top as a cane with a needle end; the SVC comes in from above and the azygos is its short side branch, Mohammad, 20 Nov)
/** anatomy.js FEEDERS[host].k: the share of the host's width its tributaries take. */
const FEEDER_K: Record<string, number> = { AZY_SVC: 1, C3: 0.5, CAUD: 0.55 };
const NETWORK_HOST_W = (e: Edge): number => widthPx(e, e.d ?? e.dMax ?? (dMinOf(e) || 3));

// ---- joins: the 2D figure's run-ons (joins.ts): the pairs that continue one another, and their courses redrawn smooth through the join ----
const JOIN_LIST: JoinEdge[] = edges.filter(isDrawnEdge).map((e) => ({ id: e.id, from: e.from, to: e.to, art: isArteryEdge(e), kind: e.kind, path: EDGE_PATH_2D[e.id]! }));
/** The pairs of vessels that run on into one another, by the 2D rule. */
// (the hepatic artery and its two branches are one tree: they meet at the hilum's node, each end joined to the others, none a blunt cap)
export const isCut = (id: string): boolean => SPLIT_AT[id] != null;   // (a vein that branches is one tube to the tip of its through branch: liver-branches.ts)
// (the end of a vein that branches is the tip of its through branch, not the node it used to end at: the vessel it ran on into in the full course is not run on into)
export const cutEnd = (id: string): number | null => (SPLIT_AT[id] == null || !isCut(id) ? null : (LIVER_BRANCH_HOSTS.out as readonly string[]).includes(id) ? 1 : 0);
export const RUN_ONS: readonly RunOn[] = findRunOns(JOIN_LIST).filter((r) => cutEnd(r.a) !== r.ia && cutEnd(r.b) !== r.ib);
const SMOOTH = smoothRunOns(new Map(JOIN_LIST.map((j) => [j.id, j.path])), RUN_ONS);
/** A vessel's 2D course as drawn: smooth through the joins where it runs on into another. */
/** A collateral or shunt ends at its node's 2D point, but the trunk veins that run on through that node are drawn smooth through the join (smooth-joins), and a fillet can move their joint a little off the node: the epigastric pair's V at the umbilicus
 *  starts 12 px from it, so the umbilical vein's end stood 5 radii from the joint and 1.8 from the vein's wall: no arm of the junction skin, no wall to sink onto (the skin dropped it, tests/skin-grow.test.ts). Its end now lies on the joint, over its last
 *  quarter (the way fitEnds moves a branch's end), wherever the trunks' drawn ends at its node agree on one point a short way (under JOINT_MAX px) from the node. Pure: the 2D courses, no list of ids. */
export const JOINT_REACH_R = 2.2;   // (about skin/inventory.ts GROW_REACH, which imports this file: tests/skin-grow.test.ts pins that twice it is no less)
const JOINT_MAX = 20, JOINT_MIN = 0.5;
type P2 = readonly [number, number];
/** The ends `atJoint` moves: which end, where it stood, the joint it goes to, and how far along the course (px) the move fades out. */
function jointMoves(e: Edge): { end: 0 | 1; own: P2; J: P2; reach: number }[] {
  const moves: { end: 0 | 1; own: P2; J: P2; reach: number }[] = [], path = EDGE_PATH_2D[e.id]!;   // (measured on the 2D course itself: what a start that leaves a wall does to the course does not change the move)
  if (e.kind !== 'collateral' && e.kind !== 'shunt') return moves;
  for (const end of [0, 1] as const) {
    const node = end ? e.to : e.from, art = isArteryEdge(e);
    const ends: P2[] = [], trunks: { r: number }[] = [];
    for (const h of edges) {
      if (h === e || !isDrawnEdge(h) || h.kind === 'collateral' || h.kind === 'shunt' || isArteryEdge(h) !== art) continue;
      const p = SMOOTH.get(h.id) ?? EDGE_PATH_2D[h.id];
      if (p && (h.from === node || h.to === node)) { ends.push(h.from === node ? p[0]! : p[p.length - 1]!); trunks.push({ r: NETWORK_HOST_W(h) / 2 }); }
    }
    if (!ends.length) continue;
    const J: P2 = [ends.reduce((s, p) => s + p[0], 0) / ends.length, ends.reduce((s, p) => s + p[1], 0) / ends.length];
    if (ends.some((p) => Math.hypot(p[0] - J[0], p[1] - J[1]) > JOINT_MIN)) continue;   // (the trunks do not meet at one point: no joint to go to)
    const own = end ? path[path.length - 1]! : path[0]!, d = Math.hypot(J[0] - own[0], J[1] - own[1]);
    if (d < JOINT_MIN || d > JOINT_MAX) continue;
    // (only an end the skin could not take as an arm: farther from the joint than twice JOINT_REACH_R radii of the widest trunk (a nearer one is an arm of its skin as it stands, or a landing on a wall, wall.ts))
    if (d <= 2 * JOINT_REACH_R * Math.max(...trunks.map((t) => t.r))) continue;
    const n = path.length, k = Math.max(1, Math.floor(0.25 * (n - 1)));
    let reach = 0;
    for (let i = 0; i < k; i++) { const a = path[end ? n - 1 - i : i]!, b = path[end ? n - 2 - i : i + 1]!; reach += Math.hypot(a[0] - b[0], a[1] - b[1]); }
    moves.push({ end, own, J, reach: reach || 1 });
  }
  return moves;
}
/** The share of a joint move a point at distance `d` (px) from the moved end takes: the whole at the end, none at `reach`, smooth between. */
export const jointFade = (d: number, reach: number): number => { const t = Math.min(1, Math.max(0, 1 - d / reach)); return t * t * (3 - 2 * t); };
function atJoint(e: Edge, path: readonly P2[]): readonly P2[] {
  const moves = jointMoves(e);
  if (!moves.length) return path;
  const out = path.map((p): [number, number] => [p[0], p[1]]), n = out.length;
  for (const m of moves) {
    let acc = 0;   // (by arc length from the end: the one rule for the course and for what hangs on it, feederPts)
    for (let q = 0; q < n; q++) {
      const i = m.end ? n - 1 - q : q;
      if (q > 0) { const prev = path[m.end ? i + 1 : i - 1]!; acc += Math.hypot(path[i]![0] - prev[0], path[i]![1] - prev[1]); }
      const w = jointFade(acc, m.reach);
      if (w <= 0) break;
      out[i]![0] += (m.J[0] - m.own[0]) * w; out[i]![1] += (m.J[1] - m.own[1]) * w;
    }
  }
  return out;
}
const basePathOf = (id: string): readonly P2[] => alongVein(id, EDGE_PATH_2D, (h) => SMOOTH.get(h) ?? EDGE_PATH_2D[h]!) ?? leaveVein(id, EDGE_PATH_2D, (h) => SMOOTH.get(h) ?? EDGE_PATH_2D[h]!) ?? withStartInOrgan(id, (id === 'A_HEP' ? undefined : SMOOTH.get(id)) ?? EDGE_PATH_2D[id]!);
const pathOf = (id: string): readonly (readonly [number, number])[] => trimHost(id, atJoint(edgeById.get(id)!, basePathOf(id)));   // (the hepatic artery's end is the node its branches start at, as it is)
/** A vessel's 2D course as the figure draws its ends: `path` (its raw 2D course) with its end moved onto the trunks' joint, as `pathOf` does. For what measures a tributary against its host (tests/landing-positions.test.ts). */
export const jointPath2D = (id: string): readonly P2[] => atJoint(edgeById.get(id)!, EDGE_PATH_2D[id]!);
/** A host's tributaries (the caput fan hangs from the umbilical vein's end) follow the host's moved end: each point shifts by the move, faded by its distance from where the end stood, so the roots stay on the host and the tree stays one piece. */
const feederPts = (host: string, pts: readonly P2[]): readonly P2[] => {
  const path = basePathOf(host), moves = jointMoves(edgeById.get(host)!);
  if (!moves.length) return pts;
  // (a point's place along the host: the arc from the moved end to the nearest point of the host's course, and its distance from the course: on the course it moves exactly as the course does, off it the move fades by the same reach)
  const place = (p: P2, end: 0 | 1): { arc: number; off: number } => {
    const n = path.length;
    let best = Infinity, arc = 0, run = 0;
    for (let q = 1; q < n; q++) {
      const i = end ? n - 1 - q : q, a = path[end ? i + 1 : i - 1]!, b = path[i]!, dx = b[0] - a[0], dy = b[1] - a[1], l = Math.hypot(dx, dy), l2 = dx * dx + dy * dy;
      const t = l2 ? Math.min(1, Math.max(0, ((p[0] - a[0]) * dx + (p[1] - a[1]) * dy) / l2)) : 0, d = Math.hypot(p[0] - a[0] - t * dx, p[1] - a[1] - t * dy);
      if (d < best) { best = d; arc = run + t * l; }
      run += l;
    }
    return { arc, off: best };
  };
  return pts.map((p): P2 => {
    let x = p[0], y = p[1];
    for (const m of moves) { const { arc, off } = place(p, m.end), w = jointFade(arc, m.reach) * jointFade(off, m.reach); x += (m.J[0] - m.own[0]) * w; y += (m.J[1] - m.own[1]) * w; }
    return [x, y];
  });
};

function build(): NetVessel[] {
  const out: NetVessel[] = [];
  for (const e of edges) {
    if (!isDrawnEdge(e)) continue;
    if (!EDGE_PATH_2D[e.id]) throw new Error(`no 2D course for ${e.id}`);
    const baseD = SHUNT_BASE_D[e.id] ?? e.d ?? e.dMax ?? (dMinOf(e) || 3);
    out.push({
      id: e.id, host: hostOfPiece.get(e.id) ?? e.id, from: e.from, to: e.to, tone: toneOf(e), radius: radiusOf(widthPx(e, baseD)),
      label: e.label ?? e.id, pts: courseOf(e.id), kind: e.kind, circFine: e.shunt === 'ap' ? AP_FINE : 1, tier: tierOf(e), baseD, widthKind: widthKindOf(e), lensId: e.id, 
      plan: { kind: 'coil', base: pathOf(e.id), coils: isCoiling(e.id, e.kind, !!e.spontaneous), strands: !!STRANDS_2D[e.id] || e.id === 'C8' },
    });
  }
  // The tributaries (stage-geo.js feedGeo): each host's, grouped by the rule that shows them, one vessel a group.
  for (const [host, list] of Object.entries(FEEDERS_2D)) {
    if (NOT_DRAWN_FEEDERS.has(host)) continue;
    const e = edgeById.get(host)!, hv = NETWORK_HOST_W(e);
    for (const when of [...new Set(list.map((f) => f.when))]) {
      const group = list.filter((f) => f.when === when).map((f) => ({ ...f, pts: feederPts(host, f.pts) as typeof f.pts }));
      const cfgK = FEEDER_K[host] ?? 1, baseD = e.d ?? e.dMax ?? (dMinOf(e) || 3);
      out.push({
        id: `${host}~F${when ? `:${when}` : ''}`, host, from: e.from, to: e.to, tone: toneOf(e), radius: radiusOf(Math.max(1.2, hv * cfgK)), label: e.label ?? host,
        pts: group[0]!.pts.map(([x, y]): Vec3 => [x3(x), y3(y), TIER_Z[tierOf(e)]]), kind: 'feeder', tier: tierOf(e), baseD, widthKind: widthKindOf(e), lensId: host,
        plan: { kind: 'feeder', list: group, cfgK, hostW: hv, when }, feeder: { host, when },
      });
    }
  }
  // The liver branches (liver-branches.ts): two children per portal-branch end, hepatic-vein start and the umbilical vein, into the liver and into depth.
  for (const b of LIVER_BRANCHES) {
    const e = edgeById.get(b.host)!, hv = NETWORK_HOST_W(e), baseD = e.d ?? e.dMax ?? (dMinOf(e) || 3);
    out.push({
      id: `${b.host}~F:b`, host: b.host, from: e.from, to: e.to, tone: toneOf(e), radius: radiusOf(Math.max(1.2, hv)), label: e.label ?? b.host,
      pts: b.list[0]!.pts.map(([x, y]): Vec3 => [x3(x), y3(y), TIER_Z[tierOf(e)]]), kind: 'feeder', tier: tierOf(e), baseD, widthKind: widthKindOf(e), lensId: b.host,
      plan: { kind: 'feeder', list: b.list, cfgK: 1, hostW: hv, when: b.when }, feeder: { host: b.host, when: b.when }, lensSpan: b.span,
    });
  }
  // The caudate lobe's three short hepatic veins, opening into the IVC (caudate-veins.ts): one tributary group on the cava's piece, shown while a slide is about the lobe (scene.ts setCaudate).
  {
    const set = caudateVeinSet(NETWORK_HOST_W(edgeById.get('IVC_IS_1')!)), e = edgeById.get(set.host)!, hv = NETWORK_HOST_W(e), baseD = e.d ?? e.dMax ?? (dMinOf(e) || 3);
    out.push({
      id: CAUDATE_VEIN_ID, host: set.host, from: e.from, to: e.to, tone: toneOf(e), radius: radiusOf(Math.max(1.2, hv * set.list[0]!.k)), label: 'Caudate lobe veins',
      pts: set.list[0]!.pts.map(([x, y]): Vec3 => [x3(x), y3(y), TIER_Z[tierOf(e)]]), kind: 'feeder', tier: tierOf(e), baseD, widthKind: widthKindOf(e), lensId: set.host,
      plan: { kind: 'feeder', list: set.list, cfgK: 1, hostW: hv, when: set.when }, feeder: { host: set.host, when: set.when }, lensSpan: set.span,
    });
  }
  return out;
}

/** Every drawn vessel, in topology order. */
export const NETWORK: readonly NetVessel[] = build();

// ---- joins: depth and width continue through a node ----
/** The depth at each node. Two vessels that join are at one depth where they meet (their own tier holds between). At a node of two the depth is the mean of their tiers (a vein that
 *  changes tier eases over its length). At a fork, a node of three or more, the widest vessels keep their own tier and the narrower ones ease to it: the mean would pull a trunk toward
 *  the camera at every branch (the cava, a back-tier vein, bulged forward at each hepatic and renal vein, and the 14 degree view turned each bulge into a sideways jog: Mohammad, 20 Nov). */
/** A vessel that starts in an organ starts at the organ's own depth: the splenic vein at the spleen's (organs/z.ts ORGAN_Z), and rises to the plane on its way to the confluence. */
const NODE_Z_AT: Readonly<Record<string, number>> = { SPL: ORGAN_Z.spleen, EPI: TIER_Z.fwd };   // (EPI: the umbilicus, on the anterior wall)
export const NODE_Z: ReadonlyMap<string, number> = (() => {
  const acc = new Map<string, { z: number; r: number; main: boolean }[]>();
  for (const v of NETWORK) if (!v.feeder) for (const n of [v.from, v.to]) { const a = acc.get(n) ?? []; a.push({ z: TIER_Z[v.tier], r: v.radius, main: v.kind !== 'shunt' && v.kind !== 'collateral' }); acc.set(n, a); }
  return new Map([...acc].map(([n, all]) => {
    // (a shunt or a collateral is drawn only in some states and is a small vessel on the trunk it joins: it eases to the node, it does not set it)
    const a = all.some((x) => x.main) ? all.filter((x) => x.main) : all;
    // (the hepatic junction too: the cava stays at its own depth through it, the hepatic veins ease down to it, and it runs on to the atrium's wall on one slope; a rise at the junction
    // and a fall to the atrium was the kink at the cava's upper end, which the 14 degree view turned into an S: Mohammad, 20 Nov)
    const widest = all.length >= 3 ? Math.max(...a.map((x) => x.r)) : 0;
    const used = a.filter((x) => x.r >= 0.9 * widest);
    return [n, NODE_Z_AT[n] ?? used.reduce((t, x) => t + x.z, 0) / used.length] as const;
  }));
})();
// Two vessels that run on into one another (a node of exactly two, or the pair the 2D rule picks at a fork) ease to one width over the last third of each (the 2D tubes' own end easing,
// tubeRadius; a branch keeps its own caliber, which the 2D figure fillets).
/** The pairs of vessel ends that meet at one width (the pair rule below), whether or not their courses carry straight on (`opposed`: outward directions within 25 degrees of opposite, the ends that need no cap). The one list the skeleton (net/skeleton.ts) reads, so it never repeats the rule. */
export interface RunPair { a: string; ea: 0 | 1; b: string; eb: 0 | 1; opposed: boolean }
export const RUN_PAIRS: RunPair[] = [];
{
  const t = new Map<NetVessel, [number, number]>();
  const pair = (a: { v: NetVessel; end: 0 | 1 }, b: { v: NetVessel; end: 0 | 1 }) => {
    if (a.v === b.v || a.v.kind === 'collateral' || b.v.kind === 'collateral' || a.v.widthKind !== b.v.widthKind) return;
    const m = (a.v.radius + b.v.radius) / 2;
    for (const x of [a, b]) { const cur = t.get(x.v) ?? [1, 1]; cur[x.end] = m / x.v.radius; t.set(x.v, cur); }
    // their courses carry on through the join (outward directions opposite, within 25 degrees): the tubes meet end to end, so neither needs its cap
    const da = outward(a.v, a.end), db = outward(b.v, b.end), opposed = !!(da && db && da[0] * db[0] + da[1] * db[1] + da[2] * db[2] < -0.9);
    if (!RUN_PAIRS.some((p) => (p.a === a.v.id && p.ea === a.end && p.b === b.v.id && p.eb === b.end) || (p.a === b.v.id && p.ea === b.end && p.b === a.v.id && p.eb === a.end))) RUN_PAIRS.push({ a: a.v.id, ea: a.end, b: b.v.id, eb: b.end, opposed });
    if (opposed) for (const x of [a, b]) { const j = x.v.joined ? [...x.v.joined] as [boolean, boolean] : [false, false] as [boolean, boolean]; j[x.end] = true; x.v.joined = j; }
  };
  const outward = (v: NetVessel, end: 0 | 1): [number, number, number] | null => {
    const p = v.pts, n = p.length, a = end ? p[n - 1]! : p[0]!, b = end ? p[n - 4 >= 0 ? n - 4 : 0]! : p[3 < n ? 3 : n - 1]!;
    const d: [number, number, number] = [a[0] - b[0], a[1] - b[1], a[2] - b[2]], l = Math.hypot(d[0], d[1], d[2]);
    return l > 1e-9 ? [d[0] / l, d[1] / l, d[2] / l] : null;
  };
  const at = new Map<string, { v: NetVessel; end: 0 | 1 }[]>();
  for (const v of NETWORK) if (!v.feeder) { for (const [n, end] of [[v.from, 0], [v.to, 1]] as const) { const a = at.get(n) ?? []; a.push({ v, end }); at.set(n, a); } }
  for (const list of at.values()) if (list.length === 2) pair(list[0]!, list[1]!);
  const byId = new Map(NETWORK.filter((v) => !v.feeder).map((v) => [v.id, v]));
  for (const r of RUN_ONS) { const a = byId.get(r.a), b = byId.get(r.b); if (a && b) pair({ v: a, end: r.ia }, { v: b, end: r.ib }); }
  for (const [v, k] of t) v.taper = k;
}
/** The vessels with a map course (everything but the fans of tributaries, which the Circuit does not draw). */
export const MAPPED: readonly NetVessel[] = NETWORK.filter((v) => !v.feeder);
// ---- forks: a branch that ends on a trunk (a node of three or more, the pair that runs on left out) blends into it with a fillet ----
{
  const at = new Map<string, { v: NetVessel; end: 0 | 1 }[]>();
  for (const v of NETWORK) if (!v.feeder && !(v.kind === 'shunt' && v.tone !== 'artery')) for (const [n, end] of [[v.from, 0], [v.to, 1]] as const) {
    const key = `${n}|${v.tone === 'artery' ? 1 : 0}`;
    const a = at.get(key) ?? []; a.push({ v, end }); at.set(key, a);
  }
  const runOn = new Set<string>();
  for (const r of RUN_ONS) { runOn.add(`${r.a}|${r.ia}`); runOn.add(`${r.b}|${r.ib}`); }
  for (const list of at.values()) {
    if (list.length < 3) continue;
    // (a vein that branches is one tube to its tip: the bed it used to run on into still continues it, so it is not a branch on a wall and wears no collar. Without this the left portal vein's bed grew a fork collar the cut had stopped
    //  counting as a run-on: in the Circuit, where the beds are drawn, a fat bulb with a slanted end stood on the vein; Mohammad, 20 Nov: "wtf happened to LPV here")
    if (list.some((e) => cutEnd(e.v.id) === e.end)) continue;
    const mains = list.filter((e) => e.v.kind !== 'collateral');
    // (a trunk drawn faint, the cava behind the organs, has no wall to blend into: the collar would show as a bulb on the branch's end)
    if (list.some((e) => IVC_EDGES.has(e.v.id))) continue;
    // (the trunk's width AT the node: two vessels that run on into one another meet at the mean of their widths, so a branch is fitted to that, not to the wider one's full width)
    const pair = list.filter((e) => runOn.has(`${e.v.id}|${e.end}`) && e.v.kind !== 'collateral');
    const meet = pair.length === 2 ? (pair[0]!.v.radius + pair[1]!.v.radius) / 2 : null;
    const widthHere = (e: { v: NetVessel; end: 0 | 1 }) => (meet != null && pair.includes(e) ? meet : e.v.radius);
    const hostR = Math.max(...(mains.length ? mains : list).map(widthHere));
    for (const { v, end } of list) {
      if (runOn.has(`${v.id}|${end}`) || v.radius >= 0.9 * hostR) continue;
      if (end === 0 && LEAVE_VEIN_IDS.has(v.id)) continue;   // (it leaves the vein's wall along its own axis, not at the node where the vein is thin: no collar there, which stood wider than the vein as a knob)
      // 2D's blend width in its own units (vein-joins.js kOf: 1.2 times the smallest radius at the join plus 1.2, 1.5 to 11), here in scene units
      const k = len3(Math.min(11, Math.max(1.5, 1.2 * (v.radius * UNITS_PER_SCENE) + 1.2)));
      const cur = v.flare ? [...v.flare] as [Flare | null, Flare | null] : [null, null] as [Flare | null, Flare | null];
      cur[end] = { add: 0.5 * k, wall: 0.8 * hostR, span: 1.5 * k };
      v.flare = cur;
    }
  }
}
export const NETWORK_BY_ID: ReadonlyMap<string, NetVessel> = new Map(NETWORK.map((v) => [v.id, v]));
/** Edge IDs the anatomy draws as vessels: what a parity row counts. */
export const DRAWN_EDGE_IDS: readonly string[] = edges.filter(isDrawnEdge).map((e) => e.id);
/** Drawn only once the paraumbilical collateral has opened (the 2D rule). */
export const NEEDS_C3_IDS = NEEDS_C3;

// ---- presence ----
export type Presence = 'shown' | 'ghost' | 'hidden';
export interface PresenceFrame { Q: ArrayLike<number>; Qf?: ArrayLike<number>; D: ArrayLike<number> }
export interface PresenceOptions { /** Blood menu: Potential collaterals (dotted routes that open with pressure) */ collaterals: boolean; /** the Circuit is showing or on its way: the liver's beds are drawn on the map (the body leaves them out) */ circuit?: boolean }
const OPEN_FRAC = 0.12, OPEN_Q = 0.3, C3_FRAC = 0.15, AP_Q = 0.3;
const indexOf = new Map(edges.map((e, i) => [e.id, i]));

/** How far a collateral has opened, 0 to 1, from its diameter between its closed and open ones (stage-frame.js recruitFrac). */
export function recruitFrac(id: string, f: PresenceFrame): number {
  const k = indexOf.get(id)!, e = edges[k]!, lo = dMinOf(e) as number, hi = e.dMax ?? lo;
  return hi > lo ? Math.min(1, Math.max(0, (f.D[k]! - lo) / (hi - lo))) : 0;
}
/** Whether a collateral is drawn open: it has grown past an eighth, or carries 0.3 mL/s. */
export function collateralOpen(id: string, f: PresenceFrame): boolean {
  const k = indexOf.get(id)!;
  return recruitFrac(id, f) > OPEN_FRAC || Math.abs((f.Qf ?? f.Q)[k]!) > OPEN_Q;
}

/** The 2D rules of stage-frame.js edgeVisible: a collateral is solid once open, a dotted thread while closed when potential collaterals are on, and nothing
 *  otherwise; the epigastric veins appear with the paraumbilical collateral; an arterioportal shunt only while it carries flow. */
export function presenceOf(v: Pick<NetVessel, 'id' | 'kind' | 'feeder'>, f: PresenceFrame, o: PresenceOptions, healthyQ?: ArrayLike<number>): Presence {
  if (v.feeder) return feederLive(v.feeder, f, healthyQ) > 0 ? 'shown' : 'hidden';
  const k = indexOf.get(v.id);
  if (k == null) return 'hidden';
  if (NEEDS_C3.has(v.id)) return recruitFrac('C3', f) > C3_FRAC ? 'shown' : 'hidden';
  // (the lumbar-azygos collateral C9 runs through the right sinusoid fan: while closed it is not drawn as a dotted pink thread there; Mohammad, 20 Nov)
  // the sinusoid beds (the "light bulb" fans, their feeding arterioles and their strands) are not drawn: the portal veins fade out into the liver and the hepatic veins fade in from it,
  // and the liver tissue implies the sinusoids between (Mohammad, 20 Nov). They stay in the network (the flows, the labels and the Lobule read them), only never shown.
  // (the Circuit draws them: 2D's map shows the portal venules dividing and the sinusoids gathering, and Mohammad wants them there, 20 Nov)
  if (v.kind === 'liver') return o.circuit ? 'shown' : 'hidden';
  if (v.kind === 'collateral') return collateralOpen(v.id, f) ? 'shown' : o.collaterals && v.id !== 'C9' ? 'ghost' : 'hidden';
  if (SHUNT_IDS.has(v.id)) return f.D[k]! > 0 ? 'shown' : 'hidden';   // a procedure's shunt is there while it has a diameter
  if (v.kind === 'shunt') return (f.Qf ?? f.Q)[k]! > AP_Q ? 'shown' : 'hidden';
  return 'shown';
}

/** How far a tributary group is on, 0 to 1 (stage-tubes.js feeders): the epigastric network fills in as the paraumbilical route opens; the caudate vein's own collaterals
 *  as its flow rises to twice and then four times the healthy one; the rest always. */
export function feederLive(fd: { host: string; when: string | null }, f: PresenceFrame, healthyQ?: ArrayLike<number>): number {
  if (fd.when === 'caput' || fd.when === 'umb') return Math.min(1, Math.max(0, (recruitFrac('C3', f) - 0.15) / 0.3));
  if (fd.when === 'caudate') {
    const k = indexOf.get(fd.host)!, ref = healthyQ?.[k], q = Math.abs((f.Qf ?? f.Q)[k]!);
    return ref ? Math.min(1, Math.max(0, (q / Math.abs(ref) - 2) / 2)) : 0;
  }
  return 1;
}
